import {services,minutes,time,addDate,validDate,shiftFor,validateVisit,planBooking,suggestSlots,seedState} from '../../../../packages/shared/src/psw-workspace/schedule-core.mjs';
export async function renderDemoPSW(root,gateway,first,api){
const KEY='primecare-psw-approval-preview-v1',BASE='2026-10-28',SCALE=1.2,START=420,END=1140;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>{const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const s=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return s.slice(0,8)+'-'+s.slice(8,12)+'-'+s.slice(12,16)+'-'+s.slice(16,20)+'-'+s.slice(20);};
const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Zm3 10h2m4 0h2m-8 4h2',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 8',check:'m5 12 4 4L19 6',clipboard:'M9 4H5v17h14V4h-4M9 2h6v5H9Zm-2 10 2 2 4-4m-6 8h10',clock:'M12 8v5l3 2m6-3a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',message:'M21 11a8 8 0 0 1-8 8H5l-4 3V11a10 10 0 1 1 20 0Z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Zm-4 10 3 3 5-6',plus:'M12 5v14M5 12h14',left:'m15 18-6-6 6-6',right:'m9 6 6 6-6 6',search:'m21 21-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z',close:'m6 6 12 12M6 18 18 6',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8m-8 4h6',alert:'m12 3 10 18H2Zm0 6v5m0 3h.01',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',route:'M5 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm14 16a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM5 7v6a3 3 0 0 0 3 3h8a3 3 0 0 0 0-6h-5',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',menu:'M3 6h18M3 12h18M3 18h18',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
let state=structuredClone(first.state),savedState=structuredClone(first.state),dbVersion=first.version,pending=false;
let page='schedule',date=BASE,view='day',mode=first.canManage?'coordinator':'psw:p1',selected=new Set(state.providers.map(p=>p.id)),discipline='all',query='',toastTimer;
const app=root,isCoordinator=()=>mode==='coordinator',me=()=>mode.startsWith('psw:')?state.providers.find(p=>p.id===mode.split(':')[1]):null;
const person=id=>state.providers.find(p=>p.id===id),client=id=>state.clients.find(c=>c.id===id),ownVisits=()=>isCoordinator()?state.visits:state.visits.filter(v=>v.providerId===me().id),ownClients=()=>isCoordinator()?state.clients:state.clients.filter(c=>ownVisits().some(v=>v.clientId===c.id));
const todayVisits=()=>ownVisits().filter(v=>v.date===date&&v.status!=='cancelled').sort((a,b)=>a.start.localeCompare(b.start));
const labelDate=(d,short=false)=>new Date(d+'T12:00:00Z').toLocaleDateString('en-CA',{weekday:short?'short':'long',month:'short',day:'numeric',...(short?{}:{year:'numeric'}),timeZone:'America/Toronto'});
const labelTime=s=>{const n=minutes(s);if(!Number.isFinite(n))return s;return (Math.floor(n/60)%12||12)+(n%60?':'+String(n%60).padStart(2,'0'):'')+(n<720?' am':' pm');};
const statusLabel=s=>({planned:'Scheduled',en_route:'On the way',in_progress:'In progress',submitted:'Notes submitted',verified:'Verified',cancelled:'Cancelled'}[s]||s);
const badge=s=>`<span class="badge ${['verified','approved'].includes(s)?'green':s==='in_progress'?'blue':s==='submitted'||s==='pending'?'amber':s==='cancelled'?'red':''}">${esc(statusLabel(s))}</span>`;
const avatar=p=>`<span class="avatar ${p.color}">${esc(p.initials)}</span>`;
const options=(items,value)=>items.map(([id,name])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('');
const field=(name,label,value='',type='text',required=true)=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const select=(name,label,items,value='',required=true)=>`<label>${esc(label)}<select name="${name}" ${required?'required':''}>${options(items,value)}</select></label>`;
const textarea=(name,label,value='',required=true)=>`<label>${esc(label)}<textarea name="${name}" maxlength="2000" ${required?'required':''}>${esc(value)}</textarea></label>`;
function toast(s){clearTimeout(toastTimer);let e=document.querySelector('#toast');if(!e){e=document.createElement('div');e.id='toast';e.setAttribute('role','status');e.setAttribute('aria-live','polite');document.body.append(e);}e.textContent=s;e.classList.add('visible');toastTimer=setTimeout(()=>e.classList.remove('visible'),4500);}
function commandValue(action,detail){
 const visit=()=>state.visits.find(v=>v.id===detail.visitId);
 if(action==='visits_booked'||action==='visit_moved')return {visits:(detail.ids||[]).map(id=>state.visits.find(v=>v.id===id)),requestId:savedState.waitlist.find(w=>!state.waitlist.some(x=>x.id===w.id))?.id};
 if(['visit_cancelled','demo_clock_start','en_route','note_draft','visit_submitted','note_verified','time_reviewed'].includes(action))return {...detail,note:visit()?.note,taskLog:visit()?.taskLog};
 if(action==='incident_recorded')return state.incidents[0];
 if(action==='incident_closed'){const i=state.incidents.find(i=>i.id===detail.incidentId);return {id:i.id,review:i.review};}
 if(action==='availability_requested')return state.availabilityRequests[0];
 if(action==='availability_changed')return {...detail,shift:state.providers.find(p=>p.id===detail.providerId).exceptions[detail.date]};
 if(action==='time_off_reviewed'){const r=state.availabilityRequests.find(r=>r.id===detail.requestId);return {id:r.id,decision:r.status,review:r.review};}
 if(action==='handover_saved')return state.messages[0];
 if(action==='unfilled_request_added')return state.waitlist.at(-1);
 if(action==='design_review_saved')return state.feedback[0];
 return detail;
}
function persist(action,detail={}){
 if(pending){state=structuredClone(savedState);return toast('Wait for the current database save to finish.');}
 const value=commandValue(action,detail);pending=true;draw();
 return api.mutate({version:dbVersion,action,value}).then(result=>{state=result.state;savedState=structuredClone(state);dbVersion=result.version;pending=false;draw();toast('Saved to the tenant’s PostgreSQL demo workspace.');return true;}).catch(error=>{state=structuredClone(savedState);pending=false;draw();toast('Not saved: '+error.message+' Refresh before retrying.');return false;});
}
function modal(title,body,{submit,onSubmit,drawer=false,footer='',onOpen}={}){const d=document.createElement('dialog');if(drawer)d.className='drawer';const previous=document.activeElement;d.innerHTML=`<form><header class="dialog-head"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-close aria-label="Close">${icon('close')}</button></header><div class="dialog-body"><p class="error" role="alert"></p>${body}</div>${submit||footer?`<footer class="dialog-footer">${footer}${submit?`<button type="button" data-close>Cancel</button><button class="primary" type="submit">${esc(submit)}</button>`:''}</footer>`:''}</form>`;document.body.append(d);const close=()=>{d.close();d.remove();if(previous?.isConnected)previous.focus();};d.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);d.addEventListener('cancel',()=>{d.remove();if(previous?.isConnected)previous.focus();});d.querySelector('form').onsubmit=e=>{e.preventDefault();if(!onSubmit)return;try{const value=Object.fromEntries(new FormData(d.querySelector('form')));onSubmit(value,d);close();}catch(error){d.querySelector('.error').textContent=error.message;}};d.showModal();onOpen?.(d,close);return d;}
function stats(){const visits=todayVisits(),hours=visits.reduce((n,v)=>n+v.duration,0)/60,done=visits.filter(v=>['submitted','verified'].includes(v.status)).length;return `<div class="stats">${[['Visits scheduled',visits.length,'calendar','teal',isCoordinator()?'Across named providers':'Assigned to '+me().name],['Planned care hours',hours.toFixed(1),'clock','purple','Travel is shown separately'],[isCoordinator()?'Providers on shift':'Visits submitted',isCoordinator()?state.providers.filter(p=>shiftFor(p,date)&&!shiftFor(p,date).off).length:done,'users','blue',isCoordinator()?'PSW · RN · physiotherapy':'Awaiting or passed review'],[isCoordinator()?'Unfilled requests':'Open follow-ups',isCoordinator()?state.waitlist.length:state.incidents.filter(x=>x.providerId===me().id&&x.status==='open').length,'alert','orange',isCoordinator()?'Review suitable slot suggestions':'Coordinator review']].map(([label,value,i,c,sub])=>`<article class="stat"><div><p>${label}</p><strong>${value}</strong><small>${esc(sub)}</small></div><span class="stat-icon ${c}">${icon(i)}</span></article>`).join('')}</div>`;}
const navItems=[['day','My day','home'],['schedule','Schedule','calendar'],['clients','Clients & care plans','users'],['visits','Visit notes & tasks','clipboard'],['handover','Handover & messages','message'],['timesheets','Timesheets','clock'],['incidents','Incidents & follow-up','shield'],['availability','Availability','calendar'],['guide','Guide & review','help']];
function draw(){const titles={schedule:['The right care. A clear schedule.','Named providers, protected time, and a plan everyone can follow.'],day:['Your day, ready for care.','Review your assigned visits, support plans and handover before setting out.'],clients:['People before paperwork.','Sample client profiles and assigned support plans, in one place.'],visits:['Every visit, clearly recorded.','Record assigned tasks, preferences, outcomes and handover.'],handover:['Keep the next person informed.','A clear handover helps the team deliver consistent care.'],timesheets:['Time that is easy to review.','Visit time and review history; demo records do not create payroll.'],incidents:['Notice. Record. Follow up.','Document an exception and keep its review visible.'],availability:['Make availability visible.','Plan shifts, protected breaks and requested time away.'],guide:['A workspace built around the visit.','Practice the complete database workflow and record improvements.']};app.innerHTML=`<div class="app"><aside class="sidebar" aria-label="Main navigation"><div class="brand"><span class="brand-icon">${icon('heart')}</span>PrimeCare</div><div><div class="workspace-label">Care workspace</div><nav>${navItems.map(([id,label,i],n)=>`${n===5?'<div class="nav-label">TEAM & OPERATIONS</div>':''}<button data-nav="${id}" class="${page===id?'active':''}">${icon(i)}${label}${id==='schedule'?`<span class="count">${todayVisits().length}</span>`:id==='incidents'&&state.incidents.filter(x=>x.status==='open').length?`<span class="count">${state.incidents.filter(x=>x.status==='open').length}</span>`:''}</button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="identity">${isCoordinator()?'<span class="avatar teal">RC</span>':avatar(me())}<div><strong>${isCoordinator()?'Rina · Coordinator':esc(me().name)}</strong><small>${isCoordinator()?'Scheduling & care operations':'Personal support worker'}</small></div></div><p class="note" style="color:#91aabc;margin:14px 0 0">DATABASE DEMO<br>Synthetic people. Saved in PostgreSQL.</p></div></aside><div class="workspace"><header class="topbar"><div class="inline"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Care delivery <span style="margin:0 9px">/</span><strong>${esc(navItems.find(n=>n[0]===page)?.[1])}</strong></div></div><div class="toolbar-right"><span class="preview-chip">DATABASE DEMO</span><label class="muted" style="font-size:10px">Practice view <select id="role-mode" class="provider-select-only" aria-label="Practice view">${options(first.canManage?[['coordinator','Coordinator'],...state.providers.filter(p=>p.role==='PSW').map(p=>['psw:'+p.id,'PSW · '+p.name])]:[['psw:p1','My PSW practice']],mode)}</select></label><button data-action="refresh">Refresh data</button><button class="icon-button" data-nav="guide" aria-label="Open help and review">${icon('help')}</button></div></header><main class="main"><div class="page-heading"><div><p class="eyebrow">${page==='schedule'?'HAMILTON · TEAM SCHEDULE':isCoordinator()?'COORDINATOR WORKSPACE':'PSW WORKSPACE'}</p><h1>${titles[page][0]}</h1><p>${titles[page][1]}</p></div><div class="actions">${page==='schedule'&&isCoordinator()?`<button data-action="waitlist">${icon('users')}Unfilled <span class="badge amber">${state.waitlist.length}</span></button><button class="primary" data-action="book">${icon('plus')}New visit</button>`:page==='incidents'?`<button class="primary" data-action="incident">${icon('plus')}Record incident</button>`:page==='handover'?`<button class="primary" data-action="message">${icon('plus')}Write handover</button>`:page==='guide'?'<button class="primary" data-action="review">Workspace feedback</button>':''}</div></div>${['schedule','day'].includes(page)?stats():''}<div class="banner"><p><strong>${esc(first.identity.organization)} · PostgreSQL demo v${dbVersion}${pending?' · saving…':''}</strong><br>All people and visits in this dataset are synthetic. ${first.liveCareAvailable?'<a href="/psw?dataset=live">Open authorized live care records</a>':'<a href="/platform/administration">Return to administration</a>'}</p>${first.scopes.length?`<select id="psw-tenant" aria-label="Demo organization">${options(first.scopes.map(x=>[x.id,x.name]),first.identity.tenantId)}</select>`:''}</div><div id="content">${renderPage()}</div><footer class="app-footer"><span>Database-backed training · synthetic records only · no live care, payroll or external messages.</span><div><button data-action="research">Research & design choices</button><button data-action="export">Export demo</button></div></footer></main></div></div>`;bind();if(pending)app.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);}
function renderPage(){return page==='schedule'?schedule():page==='day'?daySheet():page==='clients'?clientsPage():page==='visits'?visitsPage():page==='handover'?messagesPage():page==='timesheets'?timesheets():page==='incidents'?incidentsPage():page==='availability'?availabilityPage():guidePage();}
function visibleProviders(){if(!isCoordinator())return [me()];return state.providers.filter(p=>selected.has(p.id)&&(discipline==='all'||p.role===discipline));}
function schedule(){const providers=visibleProviders();return `<section class="schedule-shell"><div class="schedule-toolbar"><div class="date-nav"><button class="icon-button" data-date="prev" aria-label="Previous ${view==='week'?'week':'day'}">${icon('left')}</button><button data-date="today">Today</button><button class="icon-button" data-date="next" aria-label="Next ${view==='week'?'week':'day'}">${icon('right')}</button><input type="date" id="schedule-date" value="${date}" aria-label="Schedule date"><span class="date-label">${esc(labelDate(date,true))}</span></div><div class="inline"><div class="segmented" aria-label="Schedule view">${['day','week','agenda'].map(x=>`<button data-view="${x}" class="${view===x?'active':''}" aria-pressed="${view===x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><button class="icon-button" data-action="print" aria-label="Print schedule">${icon('file')}</button></div></div><div class="schedule-body"><aside class="provider-rail"><p><strong style="font-size:11px">Service providers</strong><br><small style="font-size:9px">Names stay visible on every visit.</small></p>${isCoordinator()?`<select id="discipline" class="provider-filter" aria-label="Filter provider discipline">${options([['all','All disciplines'],['PSW','Personal support workers'],['RN','Registered nurses'],['PT','Physiotherapists']],discipline)}</select><button data-action="all-providers" style="font-size:10px;padding:5px 8px;width:100%">Show all providers</button>`:''}${(isCoordinator()?state.providers:[me()]).map(p=>`<label class="provider-item"><input type="checkbox" data-provider="${p.id}" ${selected.has(p.id)||!isCoordinator()?'checked':''} ${!isCoordinator()?'disabled':''}>${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${p.role} · ${shiftFor(p,date)?.off?'Off':shiftFor(p,date)?labelTime(shiftFor(p,date).start):'No shift'}</small></span></label>`).join('')}<div class="rail-footer"><p class="muted" style="font-size:10px;font-weight:700">VISIT TYPES</p><div class="legend">${Object.values(services).map(s=>`<span><i class="dot" style="background:${({purple:'#9275d4',blue:'#5594c8',teal:'#429b83',orange:'#d39439',rose:'#c57898'})[s.color]}"></i>${s.name}</span>`).join('')}</div><p class="note" style="margin-top:16px;font-size:9px">${state.settings.travelBuffer}-minute travel planning buffer. Confirm real travel time before deployment.</p></div></aside><div class="board-scroll" id="schedule-board">${providers.length?(view==='day'?dayBoard(providers):view==='week'?weekBoard(providers):agendaBoard(providers)):'<div class="empty">Select at least one service provider to show a schedule.</div>'}</div></div><footer class="schedule-footer"><span>${isCoordinator()?'Click an open time to book · drag a scheduled visit to propose a move':'Your assigned schedule · select a visit to view its instructions'}</span><span>All names and visits are synthetic · Toronto time</span></footer></section>`;}
function dayBoard(providers){return `<div class="board" style="--count:${providers.length}"><div class="time-head">TIME<br>TORONTO</div>${providers.map(p=>`<div class="provider-head"><div class="name-line">${avatar(p)}<strong>${esc(p.name)}</strong></div><small>${p.role==='PT'?'Physiotherapist':p.role==='RN'?'Registered nurse':'Personal support worker'}</small><small>${shiftFor(p,date)&&!shiftFor(p,date).off?labelTime(shiftFor(p,date).start)+' – '+labelTime(shiftFor(p,date).end):'Not available'}</small></div>`).join('')}<div class="time-lane">${Array.from({length:13},(_,i)=>`<span class="time-label" style="top:${i*60*SCALE+3}px">${i+7>12?i-5:i+7}${i+7<12?'a':'p'}</span>`).join('')}</div>${providers.map(p=>{const shift=shiftFor(p,date),visits=state.visits.filter(v=>v.date===date&&v.providerId===p.id&&v.status!=='cancelled');const block=(start,end,label)=>`<div class="off-block" style="top:${(start-START)*SCALE}px;height:${(end-start)*SCALE}px">${label}</div>`;return `<div class="provider-lane" data-lane="${p.id}">${Array.from({length:24},(_,i)=>`<button class="slot" data-slot="${p.id}|${time(START+i*30)}" style="top:${i*30*SCALE}px" aria-label="${isCoordinator()?'Book':'View'} ${esc(p.name)}, ${time(START+i*30)} on ${date}" ${!isCoordinator()?'disabled':''}></button>`).join('')}${!shift||shift.off?block(START,END,'No shift'):block(START,Math.max(START,minutes(shift.start)),'')+block(Math.min(END,minutes(shift.end)),END,'')+(shift.breakStart?block(minutes(shift.breakStart),minutes(shift.breakEnd),'Break'): '')}${visits.map(v=>{const c=client(v.clientId),s=services[v.service],top=(minutes(v.start)-START)*SCALE;return `<button class="visit ${s.color} ${v.status}" data-visit="${v.id}" ${isCoordinator()&&['planned','en_route'].includes(v.status)?'draggable="true"':''} style="top:${top}px;height:${v.duration*SCALE-3}px" aria-label="${esc(c.name)}, ${s.name}, provider ${esc(p.name)}, ${labelTime(v.start)}, ${statusLabel(v.status)}"><span class="visit-time">${labelTime(v.start)} – ${labelTime(time(minutes(v.start)+v.duration))}</span><strong>${esc(c.name)}</strong><span class="service">${s.name}</span><span class="provider-name">${esc(p.name)} · ${p.role}</span>${v.duration>=75?`<span class="service">${esc(c.zone)} Hamilton · ${statusLabel(v.status)}</span>`:''}</button>${travelMarker(v,visits,shift)}`;}).join('')}</div>`;}).join('')}</div>`;}
function travelMarker(v,visits,shift){const end=minutes(v.start)+v.duration,next=visits.filter(a=>minutes(a.start)>=end).sort((a,b)=>a.start.localeCompare(b.start))[0],buffer=state.settings.travelBuffer;if(!next||next.clientId===v.clientId||!buffer)return '';let start=end;if(shift?.breakStart&&start<minutes(shift.breakEnd)&&start+buffer>minutes(shift.breakStart))start=minutes(shift.breakEnd);if(start+buffer>minutes(next.start))return '';return `<div class="travel-block" style="top:${(start-START)*SCALE}px;height:${buffer*SCALE}px">${icon('route')} ${buffer} min buffer</div>`;}
function weekBoard(providers){const day=new Date(date+'T12:00:00Z').getUTCDay(),monday=addDate(date,-(day===0?6:day-1));return `<div class="week-grid">${Array.from({length:7},(_,i)=>{const day=addDate(monday,i),visits=ownVisits().filter(v=>v.date===day&&v.status!=='cancelled'&&providers.some(p=>p.id===v.providerId)).sort((a,b)=>a.start.localeCompare(b.start));return `<div class="week-day"><div class="week-head"><small>${new Date(day+'T12:00:00Z').toLocaleDateString('en',{weekday:'short',timeZone:'America/Toronto'})}</small><strong>${Number(day.slice(-2))}</strong></div>${visits.map(v=>`<button class="week-visit" data-visit="${v.id}">${labelTime(v.start)} · ${v.duration} min<strong>${esc(client(v.clientId).name)}</strong><span>${esc(person(v.providerId).name)} · ${person(v.providerId).role}</span><span>${services[v.service].name}</span>${badge(v.status)}</button>`).join('')||'<p class="empty" style="padding:24px 0;font-size:10px">No scheduled visits</p>'}${isCoordinator()?`<button data-book-date="${day}" style="font-size:10px;width:100%">${icon('plus')}Visit</button>`:''}</div>`;}).join('')}</div>`;}
function agendaBoard(providers){const visits=todayVisits().filter(v=>providers.some(p=>p.id===v.providerId));return visits.length?`<table class="agenda"><thead><tr><th>Time</th><th>Client / service</th><th>Service provider</th><th>Area</th><th>Status</th><th></th></tr></thead><tbody>${visits.map(v=>`<tr><td>${labelTime(v.start)}<br><small>${v.duration} minutes</small></td><td><strong>${esc(client(v.clientId).name)}</strong>${services[v.service].name}</td><td><strong>${esc(person(v.providerId).name)}</strong>${person(v.providerId).role}</td><td>${esc(client(v.clientId).zone)} Hamilton</td><td>${badge(v.status)}</td><td><button data-visit="${v.id}" style="font-size:11px">Open</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No visits for this date and provider selection.</div>';}
function daySheet(){const visits=todayVisits();return `<div class="banner">${icon('clipboard')}<p><strong>Before the first visit</strong><br>Review the current assigned plan and handover, confirm travel and check your availability. This training dataset does not authorize clinical tasks or contact anyone.</p></div><div class="two-col"><section><div class="panel-header"><h2>${esc(labelDate(date))}</h2><input type="date" value="${date}" id="day-date" aria-label="My day date"></div>${visits.map(v=>`<article class="day-card"><div class="status-line"><span class="time">${labelTime(v.start)} – ${labelTime(time(minutes(v.start)+v.duration))}</span>${badge(v.status)}</div><h3>${esc(client(v.clientId).name)}</h3><p>${services[v.service].name} · ${esc(client(v.clientId).area)}<br><strong>Provider: ${esc(person(v.providerId).name)} · ${person(v.providerId).role}</strong></p><div class="actions"><button class="primary" data-visit="${v.id}">${v.status==='in_progress'?'Continue visit':'Open visit'}</button><button data-client="${v.clientId}">Care plan</button></div></article>`).join('')||'<div class="panel empty">No assigned visits on this date. Check another day or contact your coordinator.</div>'}</section><aside><section class="panel"><h3>Today’s visit flow</h3>${[['Prepare','Read the assigned plan and handover.'],['Arrive','Confirm the person’s preferences and consent.'],['Record','Resolve each assigned task and write the outcome.'],['Handover','Submit notes and report exceptions.']].map(([t,d],i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<button data-nav="guide" style="width:100%">Open the walkthrough</button></section><section class="panel"><h3>Travel & area</h3>${visits.map(v=>`<div class="row"><div><strong>${labelTime(v.start)} · ${esc(client(v.clientId).zone)} Hamilton</strong><p>${esc(person(v.providerId).name)}</p></div>${icon('route')}</div>`).join('')}<p class="note" style="margin-top:14px">Area labels are illustrative. No GPS, live map or route optimization is connected.</p></section></aside></div>`;}
function clientsPage(){const clients=ownClients().filter(c=>!query||c.name.toLowerCase().includes(query));return `<div class="panel-header"><p class="muted">${isCoordinator()?'All demo clients':'Clients assigned to '+esc(me().name)} · care-plan references are read-only.</p><input id="client-search" placeholder="Search a client name" aria-label="Search clients" value="${esc(query)}"></div><div class="list-grid">${clients.map(c=>`<article class="client-card"><div class="identity"><span class="avatar teal">${c.initials}</span><div><h3>${esc(c.name)}</h3><small>${esc(c.area)}</small></div></div><p>${esc(c.preferences)}</p><p><strong>Preferred provider</strong><br>${esc(person(c.preferredProviderId).name)} · ${person(c.preferredProviderId).role}</p><p><span class="badge green">Demo support plan</span></p><button data-client="${c.id}">Open profile & care plan</button></article>`).join('')||'<div class="panel empty">No matching assigned clients.</div>'}</div>`;}
function visitsPage(){const visits=ownVisits().filter(v=>v.status!=='cancelled').sort((a,b)=>b.date.localeCompare(a.date)||a.start.localeCompare(b.start));return `<div class="banner">${icon('shield')}<p>Record facts and client preferences. Completion of a support task is separate from a clinical assessment. All examples here are synthetic and saved in the tenant’s demo workspace.</p></div><section class="panel"><div class="panel-header"><h2>Visit records</h2><span class="badge">${visits.length} records</span></div>${visits.map(v=>`<div class="row"><div><strong>${esc(client(v.clientId).name)} · ${services[v.service].name}</strong><p>${labelDate(v.date,true)} · ${labelTime(v.start)} · ${esc(person(v.providerId).name)}</p><p>${v.note?esc(v.note.slice(0,90)):'No visit note submitted.'}</p></div><div class="actions">${badge(v.status)}<button data-visit="${v.id}">Open</button></div></div>`).join('')||'<div class="empty">No assigned visit records.</div>'}</section>`;}
function messagesPage(){const messages=state.messages.filter(m=>isCoordinator()||m.to===me().id||m.providerId===me().id||m.to==='team');return `<div class="banner amber">${icon('message')}<p><strong>Demo handover only.</strong> This saves a handover record in PostgreSQL; it does not send email, SMS or an external alert. Use live care’s approved handover workflow for real recipients and care-team review.</p></div><div class="two-col"><section class="panel"><h2>Handover notebook</h2>${messages.map(m=>`<article class="message"><div class="status-line"><strong>${esc(m.subject)}</strong><span class="badge">Database demo</span></div><small>${esc(m.from)} → ${m.to==='coordinator'?'Coordinator':m.to==='team'?'Demo team':esc(person(m.to)?.name||m.to)}</small><p>${esc(m.text)}</p><small>${new Date(m.at).toLocaleString('en-CA',{timeZone:'America/Toronto'})}</small></article>`).join('')||'<div class="empty">No demo handover messages yet.</div>'}</section><aside class="panel"><h3>A useful handover includes</h3>${['The visit and named provider','What the person chose or declined','Factual observations and changes','What needs review and who owns it','When the next follow-up is expected'].map((t,i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><p>${t}</p></div>`).join('')}<button class="primary" data-action="message">Write a demo handover</button></aside></div>`;}
function timesheets(){const rows=ownVisits().filter(v=>v.clockOut),total=rows.reduce((n,v)=>n+(v.reportedMinutes??Math.floor((v.clockOut-v.clockIn)/60000)),0);return `<div class="stats">${[['Recorded visit time',(total/60).toFixed(2)+' h'],['Visits recorded',rows.length],['Awaiting review',rows.filter(v=>!v.timesheetApproved).length],['Approved records',rows.filter(v=>v.timesheetApproved).length]].map(([t,n])=>`<article class="stat"><div><p>${t}</p><strong>${n}</strong></div></article>`).join('')}</div><section class="panel"><div class="panel-header"><div><h2>Visit-time review</h2><p class="muted">Elapsed or corrected time is separate from planned duration.</p></div><button data-action="csv">${icon('download')}Export CSV</button></div>${rows.length?`<div class="table-scroll"><table class="agenda"><thead><tr><th>Date / visit</th><th>Provider</th><th>Planned</th><th>Recorded</th><th>Review</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${v.date}</strong>${esc(client(v.clientId).name)}</td><td>${esc(person(v.providerId).name)}</td><td>${v.duration} min</td><td>${v.reportedMinutes??Math.floor((v.clockOut-v.clockIn)/60000)} min<br><small>${v.timeCorrectionReason?'Manager-corrected':'Elapsed demo clock time'}</small></td><td>${badge(v.timesheetApproved?'approved':'pending')}</td><td>${isCoordinator()?`<button data-time-review="${v.id}">Review time</button>`:'Coordinator review'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">'+icon('clock')+'<h3>No visit time recorded yet</h3><p>Open a visit, start the demo clock, resolve tasks and submit your note. Then return here.</p><button data-nav="day">Go to My day</button></div>'}<p class="note" style="margin-top:18px">This preview does not calculate wages, send payroll, track location, or treat a planned visit as time worked.</p></section>`;}
function incidentsPage(){const incidents=state.incidents.filter(x=>isCoordinator()||x.providerId===me().id);return `<div class="banner amber">${icon('alert')}<p>If immediate help is needed, follow the organization’s emergency procedure. This demo cannot call emergency services or notify the coordinator.</p></div><section class="panel"><div class="panel-header"><h2>Exception and follow-up log</h2><span class="badge amber">${incidents.filter(i=>i.status==='open').length} open</span></div>${incidents.map(i=>`<article class="message"><div class="status-line"><strong>${esc(i.type)} · ${esc(client(i.clientId)?.name||'Service concern')}</strong>${badge(i.status)}</div><p>${esc(i.facts)}</p><p><strong>Immediate action:</strong> ${esc(i.action)}</p><p><strong>Next follow-up:</strong> ${esc(i.followup)}</p><small>${esc(person(i.providerId)?.name||'Coordinator')} · ${labelDate(i.date,true)}</small>${i.review?`<p><strong>Review:</strong> ${esc(i.review)}</p>`:''}${isCoordinator()&&i.status==='open'?`<p><button data-incident-review="${i.id}">Record review & close</button></p>`:''}</article>`).join('')||'<div class="empty">'+icon('shield')+'<h3>No demo incidents recorded</h3><p>Use “Record incident” to test the exception and review workflow.</p></div>'}</section>`;}
function availabilityPage(){const providers=isCoordinator()?state.providers:[me()];return `${isCoordinator()?`<section class="panel"><div class="panel-header"><div><h3>Between-client travel buffer</h3><p class="muted">A planning minimum, not a real route estimate. Existing visits must still fit.</p></div></div><form id="buffer-form" class="inline">${field('minutes','Travel planning minutes',String(state.settings.travelBuffer),'number')}<button class="primary" type="submit">Save demo buffer</button><span class="error" role="alert" data-buffer-error></span></form></section>`:''}<div class="banner">${icon('clock')}<p>Shift and break changes are checked against existing visits. PSWs request changes; the coordinator reviews them. No provider’s real availability is changed.</p></div><section class="panel"><div class="panel-header"><h2>${esc(labelDate(date))}</h2><input type="date" id="availability-date" value="${date}" aria-label="Availability date"></div>${providers.map(p=>{const shift=shiftFor(p,date);return `<div class="row"><div class="identity">${avatar(p)}<div><strong>${esc(p.name)} · ${p.role}</strong><p>${!shift||shift.off?'Not available':labelTime(shift.start)+' – '+labelTime(shift.end)+' · break '+labelTime(shift.breakStart)+' – '+labelTime(shift.breakEnd)}</p></div></div><button data-availability="${p.id}">${isCoordinator()?'Edit shift':'Request time off'}</button></div>`;}).join('')}</section><section class="panel"><h2>Availability requests</h2>${state.availabilityRequests.filter(r=>isCoordinator()||r.providerId===me().id).map(r=>`<div class="row"><div><strong>${esc(person(r.providerId).name)} · ${r.date}</strong><p>${esc(r.reason)}</p>${r.review?`<p>${esc(r.review)}</p>`:''}</div><div class="actions">${badge(r.status)}${isCoordinator()&&r.status==='pending'?`<button data-availability-review="${r.id}">Review request</button>`:''}</div></div>`).join('')||'<p class="muted">No availability requests in this demo.</p>'}</section>`;}
function guidePage(){return `<div class="two-col"><section class="panel"><h2>Database-backed practice workflow</h2>${[['Choose the dataset','This is the saved synthetic training dataset for this organization. Live care is a separate authorized view.'],['Schedule named providers','Book, move, repeat or cancel a demo visit. The API repeats the service, shift, break, overlap and travel checks before saving.'],['Record an assigned visit','Use a PSW practice view, start the demo visit, record completed, declined or held task outcomes, and submit a note.'],['Review the work','Coordinator practice includes note verification, incident follow-up and time review. These actions do not create real clinical approvals or payroll.'],['Refresh and read back','Use Refresh data or reload the page to read the saved database version. Concurrent changes are rejected rather than overwritten.'],['Use live care safely','Open the live care workspace with a clinical or care-operations account. Existing nurse, supervisor and PSW permissions remain in force.']].map(([t,p],i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</section><aside><section class="panel"><h3>Saved in PostgreSQL</h3><p class="note">Bookings, visit outcomes, notes, handover, incidents, availability, time reviews and feedback are saved through the authenticated API. Each organization has separate data. Ordinary staff use a private practice workspace.</p><div class="approval-note">All names and visits here are synthetic. Never enter real care records into training data.</div><div class="actions" style="margin-top:15px"><button data-action="export">Export saved snapshot</button><button data-action="review">Workspace feedback</button><button class="danger" data-action="reset">Reset synthetic practice</button></div></section><section class="panel"><h3>Scheduling design</h3><p class="note">Jane-inspired named-provider columns, day/week views and appointment panels, adapted for home-care travel and protected breaks.</p><button data-action="research">Research & design choices</button></section></aside></div>`;}
function canOpen(v){return isCoordinator()||v.providerId===me()?.id;}
function visitModal(id){const v=state.visits.find(v=>v.id===id);if(!v||!canOpen(v))return toast('This visit is not assigned to this demo PSW.');const p=person(v.providerId),c=client(v.clientId),active=['planned','en_route','in_progress'].includes(v.status),editable=['planned','en_route'].includes(v.status);modal(c.name,`<div class="status-line"><span class="badge ${services[v.service].color==='purple'?'purple':'blue'}">${services[v.service].name}</span>${badge(v.status)}</div><div class="detail-block"><div class="provider-detail">${avatar(p)}<div><strong>${esc(p.name)} · ${p.role}</strong><small>Assigned service provider</small></div></div><p style="margin-top:13px">${esc(labelDate(v.date))}<br><strong>${labelTime(v.start)} – ${labelTime(time(minutes(v.start)+v.duration))}</strong> · ${v.duration} minutes<br>${esc(c.area)}</p></div><div class="detail-block"><h3>Care instructions & preferences</h3><p>${esc(c.plan)}</p><p>${esc(c.preferences)}</p>${c.alerts.map(a=>`<p><span class="badge amber">Read first</span> ${esc(a)}</p>`).join('')}<button type="button" data-open-profile style="margin-top:10px;font-size:11px">Read client & support plan</button></div>${v.status==='in_progress'||['submitted','verified'].includes(v.status)?`<h3>Assigned tasks</h3>${c.tasks.map((t,i)=>`<div class="task-log"><span>${esc(t)}</span><select name="task_${i}" aria-label="Outcome for task ${i+1}" ${!active?'disabled':''}>${options([['','Choose outcome'],['done','Completed'],['declined','Declined'],['held','Held / follow-up']],v.taskLog?.[i]||'')}</select></div>`).join('')}<div style="margin-top:17px">${textarea('note','Visit note & handover',v.note||'',true)}</div><p class="note">Record what happened, choices, unresolved needs and follow-up. No real personal or clinical information in this demo.</p>`:v.status==='cancelled'?`<div class="banner amber"><p>Cancelled: ${esc(v.cancelReason)}</p></div>`:'<div class="banner"><p>Read the assigned plan first. “Start demo visit” simulates arrival and starts an elapsed-time clock. It does not verify attendance or location.</p></div>'}${v.clockIn?`<p class="note">Demo clock started: ${new Date(v.clockIn).toLocaleTimeString('en-CA',{timeZone:'America/Toronto'})}${v.clockOut?' · elapsed '+Math.floor((v.clockOut-v.clockIn)/60000)+' min':''}</p>`:''}<div class="actions" style="margin-top:15px">${editable?`<button type="button" data-start class="primary">${icon('check')}Start demo visit</button>${v.status==='planned'?'<button type="button" data-enroute>Mark on the way</button>':''}`:''}${v.status==='in_progress'?'<button type="button" data-note-save>Save note draft</button>':''}${active?'<button type="button" data-incident>Record exception</button>':''}${isCoordinator()&&editable?'<button type="button" data-edit>Move / edit visit</button><button type="button" data-cancel class="danger">Cancel visit</button>':''}${isCoordinator()&&v.status==='submitted'?'<button type="button" data-verify class="primary">Review & verify note</button>':''}</div><details style="margin-top:20px"><summary class="muted">Visit history</summary>${(v.history||[]).map(h=>`<p class="note">${esc(h.action)} · ${esc(h.detail||'')}<br>${new Date(h.at).toLocaleString('en-CA',{timeZone:'America/Toronto'})}</p>`).join('')||'<p class="note">No changes recorded in this demo visit yet.</p>'}</details>`,{drawer:true,submit:v.status==='in_progress'?'Submit note & end demo visit':null,onSubmit:values=>{for(let i=0;i<c.tasks.length;i++)if(!['done','declined','held'].includes(values['task_'+i]))throw Error('Record an outcome for every assigned task.');if(values.note.trim().length<10)throw Error('Write a meaningful demo visit note (at least 10 characters).');v.note=values.note.trim();v.taskLog=Object.fromEntries(c.tasks.map((_,i)=>[i,values['task_'+i]]));v.status='submitted';v.clockOut=Date.now();v.history.push({at:new Date().toISOString(),action:'Visit note submitted',detail:'Task outcomes and note recorded for coordinator review.'});persist('visit_submitted',{visitId:v.id,provider:p.name});},onOpen:(d,close)=>{d.querySelector('textarea[name=note]')?.toggleAttribute('readonly',!active);d.querySelector('[data-open-profile]').onclick=()=>{close();clientModal(c.id);};d.querySelector('[data-start]')?.addEventListener('click',()=>{v.status='in_progress';v.clockIn=Date.now();v.history.push({at:new Date().toISOString(),action:'Demo visit started'});close();persist('demo_clock_start',{visitId:v.id}).then(saved=>{if(saved)visitModal(v.id);});});d.querySelector('[data-enroute]')?.addEventListener('click',()=>{v.status='en_route';v.history.push({at:new Date().toISOString(),action:'Marked on the way'});close();persist('en_route',{visitId:v.id});});d.querySelector('[data-note-save]')?.addEventListener('click',()=>{const values=Object.fromEntries(new FormData(d.querySelector('form')));v.note=values.note;v.taskLog=Object.fromEntries(c.tasks.map((_,i)=>[i,values['task_'+i]]));v.history.push({at:new Date().toISOString(),action:'Note draft saved'});close();persist('note_draft',{visitId:v.id});});d.querySelector('[data-edit]')?.addEventListener('click',()=>{close();bookingModal({visit:v});});d.querySelector('[data-cancel]')?.addEventListener('click',()=>{close();modal('Cancel this visit',textarea('reason','Cancellation reason'),{submit:'Cancel demo visit',onSubmit:x=>{v.status='cancelled';v.cancelReason=x.reason;v.history.push({at:new Date().toISOString(),action:'Cancelled',detail:x.reason});persist('visit_cancelled',{visitId:v.id,reason:x.reason});}});});d.querySelector('[data-incident]')?.addEventListener('click',()=>{close();incidentModal(v);});d.querySelector('[data-verify]')?.addEventListener('click',()=>{close();modal('Review submitted visit note',`<p class="note">Review the recorded task outcomes and note; verification here is a demo management action, not a clinical approval.</p>${textarea('review','Review rationale')}<label class="checkline"><input name="checked" type="checkbox" required>I reviewed the note, choices and unresolved follow-up.</label>`,{submit:'Verify demo note',onSubmit:x=>{v.status='verified';v.history.push({at:new Date().toISOString(),action:'Note verified in demo',detail:x.review});persist('note_verified',{visitId:v.id,review:x.review});}});});}});}
function clientModal(id){const c=ownClients().find(c=>c.id===id);if(!c)return;modal(c.name,`<div class="identity" style="margin-bottom:20px"><span class="avatar teal">${c.initials}</span><div><strong>${esc(c.name)}</strong><br><small>${esc(c.area)} · synthetic client</small></div></div><div class="detail-block"><h3>Preferences & continuity</h3><p>${esc(c.preferences)}</p><p>Preferred provider: <strong>${esc(person(c.preferredProviderId).name)}</strong></p><p>Contact: ${c.contact} · not connected</p></div><div class="detail-block"><h3>Assigned support plan</h3><p>${esc(c.plan)}</p>${c.tasks.map((t,i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><p>${esc(t)}</p></div>`).join('')}<p class="note">This plan is a read-only demonstration. Changes to real care plans require the organization’s authorized process.</p></div><h3>Scheduled providers</h3>${ownVisits().filter(v=>v.clientId===c.id&&v.status!=='cancelled').map(v=>`<div class="row"><div><strong>${esc(person(v.providerId).name)} · ${person(v.providerId).role}</strong><p>${v.date} · ${labelTime(v.start)} · ${services[v.service].name}</p></div>${badge(v.status)}</div>`).join('')}`,{drawer:true,footer:'<button type="button" data-close>Close profile</button>'});}
function bookingModal({providerId,at,day,visit,request,chosen}={}){if(!isCoordinator())return toast('A coordinator manages bookings.');const v=visit||chosen||{},selectedClient=v.clientId||request?.clientId||state.clients[0].id;modal(visit?'Move / edit visit':'Book a visit',`<div class="banner"><p>Choose a named provider. The demo checks service qualifications, shifts, breaks, client overlaps and a ${state.settings.travelBuffer}-minute travel planning buffer.</p></div><div class="form-grid"><div class="full">${select('clientId','Client',state.clients.map(c=>[c.id,c.name+' · '+c.zone+' Hamilton']),selectedClient)}</div><div class="full">${select('service','Service',Object.entries(services).map(([id,s])=>[id,s.name]),v.service||request?.service||'personal')}</div><div class="full">${select('providerId','Service provider (named)',state.providers.map(p=>[p.id,p.name+' · '+p.role]),v.providerId||providerId||'p1')}</div>${field('date','Visit date',v.date||day||date,'date')}${field('start','Start time',v.start||at||'09:00','time')}${select('duration','Duration',[[30,'30 minutes'],[45,'45 minutes'],[60,'1 hour'],[90,'1½ hours'],[120,'2 hours'],[180,'3 hours'],[240,'4 hours']],String(v.duration||request?.duration||60))}${!visit?select('repeat','Repeat',[[1,'This visit only'],[2,'Weekly · 2 visits'],[4,'Weekly · 4 visits']].map(([a,b])=>[String(a),b]),'1'):'<input type="hidden" name="repeat" value="1">'}<div class="full">${textarea('reason',visit?'Reason for moving / changing':'Booking instructions',visit?'':request?.note||'Demo visit within the assigned support plan.')}</div></div><p class="note">Repeats are saved together only if every occurrence is conflict-free. No confirmation email or SMS is sent.</p>`,{submit:visit?'Confirm demo change':'Book demo visit',onSubmit:x=>{const created=planBooking(x,state,{ignoreId:visit?.id||'',repeat:Number(x.repeat),idFactory:uid});for(const a of created){a.bookingInstructions=x.reason;a.history=visit?[...(visit.history||[]),{at:new Date().toISOString(),action:'Visit moved / edited',detail:x.reason}]:[{at:new Date().toISOString(),action:'Booked in demo',detail:x.reason}];}state.visits=state.visits.filter(a=>a.id!==visit?.id);state.visits.push(...created);if(request)state.waitlist=state.waitlist.filter(w=>w.id!==request.id);date=x.date;persist(visit?'visit_moved':'visits_booked',{ids:created.map(x=>x.id),provider:person(x.providerId).name,repeat:created.length});},onOpen:d=>{d.querySelector('[name=service]').addEventListener('change',e=>{const service=services[e.target.value],p=d.querySelector('[name=providerId]');const current=person(p.value);if(!service.roles.includes(current.role))p.value=state.providers.find(x=>service.roles.includes(x.role)).id;});}});}
function waitlistModal(){if(!isCoordinator())return;modal('Unfilled visit requests',`<p class="note">Suggestions prefer provider continuity and familiar areas, then lower scheduled workload and earlier compatible times. These are planning suggestions, not live route optimization.</p>${state.waitlist.map(w=>`<article class="detail-block"><h3>${esc(client(w.clientId).name)}</h3><p>${services[w.service].name} · ${w.duration} minutes<br>${labelTime(w.from)} – ${labelTime(w.to)} · ${esc(client(w.clientId).zone)} Hamilton</p><p>${esc(w.note)}</p><button type="button" data-suggest="${w.id}">${icon('spark')}Suggest suitable slots</button><div id="suggest-${w.id}"></div></article>`).join('')||'<div class="empty">All demo requests are filled.</div>'}`,{drawer:true,footer:'<button type="button" data-add-request>New unfilled request</button>',onOpen:(d,close)=>{d.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{const w=state.waitlist.find(w=>w.id===b.dataset.suggest),suggestions=suggestSlots(w,state,date),container=d.querySelector('#suggest-'+w.id);container.innerHTML=suggestions.length?suggestions.map((s,i)=>`<div class="row"><div><strong>${esc(person(s.providerId).name)}</strong><p>${labelDate(s.date,true)} · ${labelTime(s.start)}<br>${esc(s.reason)}</p></div><button type="button" data-choose="${i}">Choose</button></div>`).join(''):'<p class="note">No suitable slots on this date. Try another date or review availability.</p>';container.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{close();bookingModal({request:w,chosen:suggestions[Number(b.dataset.choose)]});});});d.querySelector('[data-add-request]').onclick=()=>{close();modal('Add an unfilled request',`<div class="form-grid"><div class="full">${select('clientId','Client',state.clients.map(c=>[c.id,c.name]))}</div><div class="full">${select('service','Requested service',Object.entries(services).map(([k,s])=>[k,s.name]))}</div>${field('from','Available from','09:00','time')}${field('to','Available until','17:00','time')}<div class="full">${textarea('note','Preferences or request details')}</div></div>`,{submit:'Save demo request',onSubmit:v=>{if(minutes(v.to)-minutes(v.from)<60)throw Error('Choose a window of at least 60 minutes.');state.waitlist.push({...v,id:uid(),duration:60});persist('unfilled_request_added',{clientId:v.clientId});}});};}});}
function incidentModal(visit){const clients=ownClients();modal('Record an incident / exception',`<div class="banner amber"><p>This does not notify anyone. Follow your organization’s real escalation process if help is needed.</p></div><div class="form-grid"><div class="full">${select('clientId','Client',clients.map(c=>[c.id,c.name]),visit?.clientId||clients[0]?.id)}</div><div class="full">${select('type','Type',[['Service exception','Service exception'],['Client choice / declined activity','Client choice / declined activity'],['Safety concern','Safety concern'],['Missed / delayed visit','Missed / delayed visit'],['Other follow-up','Other follow-up']])}</div>${field('date','Date',date,'date')}<div class="full">${textarea('facts','Factual description — demo only')}</div><div class="full">${textarea('action','Immediate action taken')}</div><div class="full">${textarea('followup','Required follow-up and responsible person')}</div></div>`,{submit:'Save demo incident',onSubmit:v=>{if(!validDate(v.date))throw Error('Choose a valid date.');state.incidents.unshift({...v,id:uid(),providerId:visit?.providerId||me()?.id||'',visitId:visit?.id||'',status:'open'});persist('incident_recorded',{type:v.type,clientId:v.clientId});}});}
function messageModal(){modal('Write a demo handover',`<div class="banner amber"><p>Saved in PostgreSQL as a practice handover. No external message is transmitted.</p></div><div class="form-grid"><div class="full">${select('to','Intended recipient',isCoordinator()?state.providers.map(p=>[p.id,p.name+' · '+p.role]):[['coordinator','Coordinator']])}</div><div class="full">${field('subject','Subject')}</div><div class="full">${textarea('text','Handover message — synthetic information only')}</div></div>`,{submit:'Save demo handover',onSubmit:v=>{state.messages.unshift({...v,id:uid(),from:isCoordinator()?'Rina · demo coordinator':me().name+' · demo PSW',providerId:me()?.id||'',at:new Date().toISOString()});persist('handover_saved',{recipient:v.to});}});}
function timeReview(id){const v=state.visits.find(v=>v.id===id);if(!isCoordinator()||!v.clockOut)return;modal('Review recorded time',`<p><strong>${esc(person(v.providerId).name)}</strong><br>${esc(client(v.clientId).name)} · ${v.date}</p><p class="note">Planned: ${v.duration} min. Demo elapsed: ${Math.floor((v.clockOut-v.clockIn)/60000)} min. Use a reason if correcting recorded time.</p><div class="form-grid"><div class="full">${field('minutes','Reviewed minutes',String(v.reportedMinutes??Math.floor((v.clockOut-v.clockIn)/60000)),'number')}</div><div class="full">${textarea('reason','Review evidence / correction reason')}</div><div class="full"><label class="checkline"><input name="reviewed" type="checkbox" required>I checked this synthetic time record.</label></div></div>`,{submit:'Approve demo time record',onSubmit:x=>{const n=Number(x.minutes);if(!Number.isInteger(n)||n<0||n>720)throw Error('Use whole minutes from 0 to 720.');v.reportedMinutes=n;v.timeCorrectionReason=x.reason;v.timesheetApproved=true;v.history.push({at:new Date().toISOString(),action:'Time record reviewed',detail:x.reason});persist('time_reviewed',{visitId:id,minutes:n,reason:x.reason});}});}
function availabilityModal(providerId){const p=person(providerId);if(!isCoordinator()&&p.id!==me().id)return;if(!isCoordinator()){modal('Request time off',`<p><strong>${esc(p.name)}</strong> · ${esc(labelDate(date))}</p>${textarea('reason','Reason and proposed coverage / handover')}`,{submit:'Save demo request',onSubmit:v=>{state.availabilityRequests.unshift({id:uid(),providerId:p.id,date,reason:v.reason,status:'pending'});persist('availability_requested',{providerId:p.id,date});}});return;}const shift=shiftFor(p,date)||p.shift;modal('Edit shift · '+p.name,`<p class="note">This changes this date only. Existing visits must still fit the shift and protected break.</p><div class="form-grid">${field('start','Shift starts',shift.start,'time')}${field('end','Shift ends',shift.end,'time')}${field('breakStart','Break starts',shift.breakStart,'time')}${field('breakEnd','Break ends',shift.breakEnd,'time')}<div class="full"><label class="checkline"><input name="off" type="checkbox" ${shift.off?'checked':''}>Not available on this date</label></div><div class="full">${textarea('reason','Reason / confirmation')}</div></div>`,{submit:'Save demo availability',onSubmit:x=>{if(minutes(x.start)>=minutes(x.end)||minutes(x.start)<START||minutes(x.end)>END)throw Error('Use a shift between 7 am and 7 pm, ending after it starts.');if(minutes(x.breakStart)<minutes(x.start)||minutes(x.breakEnd)>minutes(x.end)||minutes(x.breakEnd)<=minutes(x.breakStart))throw Error('The protected break must fall within the shift.');const candidate=structuredClone(state),changed=candidate.providers.find(q=>q.id===p.id);changed.exceptions||={};changed.exceptions[date]={...x,off:x.off==='on'};for(const v of candidate.visits.filter(v=>v.providerId===p.id&&v.date===date&&v.status!=='cancelled')){const error=validateVisit(v,candidate,v.id);if(error)throw Error('Existing visits conflict. Reassign or move those visits before changing this shift.');}p.exceptions||={};p.exceptions[date]=changed.exceptions[date];persist('availability_changed',{providerId:p.id,date,reason:x.reason});}});}
function reviewAvailability(id){const r=state.availabilityRequests.find(r=>r.id===id);if(!isCoordinator()||!r||r.status!=='pending')return;modal('Review time-off request',`<p><strong>${esc(person(r.providerId).name)}</strong> · ${r.date}</p><p>${esc(r.reason)}</p>${select('decision','Decision',[['approved','Approve time off'],['declined','Decline / discuss alternatives']])}${textarea('review','Review and coverage details')}`,{submit:'Save demo decision',onSubmit:v=>{if(v.decision==='approved'&&state.visits.some(x=>x.providerId===r.providerId&&x.date===r.date&&x.status!=='cancelled'))throw Error('Move or reassign existing visits before approving time off.');if(v.decision==='approved'){const p=person(r.providerId);p.exceptions||={};p.exceptions[r.date]={...p.shift,off:true};}r.status=v.decision;r.review=v.review;persist('time_off_reviewed',{requestId:r.id,decision:v.decision});}});}
function researchModal(){modal('Research & design choices',`<h3>What Jane’s official guides show</h3><p class="note">Jane supports named practitioner lists, day/week schedule views, provider shifts and breaks, open-time booking, appointment panels, moving appointments and waitlists. These patterns inform this original PrimeCare prototype.</p><div class="detail-block"><p><a href="https://jane.app/guide/working-with-the-schedule" target="_blank" rel="noopener noreferrer">Working with the schedule</a></p><p><a href="https://jane.app/guide/booking-changing-or-moving-an-appointment-staff" target="_blank" rel="noopener noreferrer">Booking, changing or moving an appointment</a></p><p><a href="https://jane.app/guide/using-the-wait-list" target="_blank" rel="noopener noreferrer">Using the wait list</a></p></div><h3>Our home-care adaptation</h3><p class="note">Provider names remain visible in every view. A visit must match the provider’s service role and shift, avoid protected breaks and overlapping client/provider visits, and leave the configured travel buffer between different clients. Unlike a clinic that may allow overlapping appointments, this PSW demo blocks double bookings.</p><p class="note">Slot suggestions consider continuity, familiar area, scheduled workload and the requested window. They are not a live routing system, a guarantee of availability, or a clinical staffing decision.</p><h3>Approval boundary</h3><p class="note">This saved training dataset is separate from live care records. Authenticated access, tenant isolation, optimistic versions and audit events are enforced by the API. Live care uses the existing care-team approval rules and clinical records.</p>`,{footer:'<button type="button" data-close>Close research</button>'});}
function reviewModal(){modal('Workspace feedback',`<div class="approval-note">Your feedback is stored in the database demo workspace. It does not change clinical permissions or approve real care. Please also tell us your decision in chat.</div><div style="margin-top:18px">${select('decision','Feedback category',[['changes','I need a workflow improvement'],['ready','Workflow works for my practice']])}</div><div style="margin-top:15px">${textarea('comment','What works, what should change, and which view you tested')}</div>`,{submit:'Save database feedback',onSubmit:v=>{state.feedback.unshift({...v,at:new Date().toISOString()});persist('design_review_saved',{decision:v.decision});}});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csvExport(){const rows=[['Date','Provider','Role','Client (synthetic)','Service','Planned minutes','Recorded minutes','Time review'],...ownVisits().filter(v=>v.clockOut).map(v=>[v.date,person(v.providerId).name,person(v.providerId).role,client(v.clientId).name,services[v.service].name,v.duration,v.reportedMinutes??Math.floor((v.clockOut-v.clockIn)/60000),v.timesheetApproved?'approved':'pending'])];const csv=rows.map(row=>row.map(x=>'"'+String(/^[=+\-@]/.test(String(x))?"'"+x:x).replaceAll('"','""')+'"').join(',')).join('\r\n');download('PrimeCare_Demo_Timesheets.csv',csv,'text/csv;charset=utf-8');toast('Synthetic timesheet CSV exported. No payroll was sent.');}
function action(name){if(name==='refresh'){if(pending)return;pending=true;draw();void api.read('demo').then(result=>{state=result.state;savedState=structuredClone(state);dbVersion=result.version;Object.assign(first,result);if(!first.canManage)mode='psw:p1';pending=false;draw();toast('Refreshed from PostgreSQL.');}).catch(e=>{pending=false;draw();toast(e.message);});return;}if(name==='book')bookingModal();else if(name==='waitlist')waitlistModal();else if(name==='message')messageModal();else if(name==='incident')incidentModal();else if(name==='research')researchModal();else if(name==='review')reviewModal();else if(name==='print')window.print();else if(name==='csv')csvExport();else if(name==='export'){download('PrimeCare_PSW_Demo.json',JSON.stringify({prototype:'PrimeCare PSW approval preview',synthetic:true,exportedAt:new Date().toISOString(),...state},null,2),'application/json');toast('Synthetic demo data exported.');}else if(name==='all-providers'){selected=new Set(state.providers.map(p=>p.id));discipline='all';draw();}else if(name==='menu'){document.querySelector('.sidebar').classList.toggle('open');}else if(name==='reset')modal('Reset synthetic demo data',`<p>This resets visits, notes, incidents, messages, time records, reviews and availability changes stored by this demo workspace.</p><p class="note">Export the demo first if you want to keep your work. It does not affect live care records.</p>`,{submit:'Reset demo',onSubmit:()=>{state=seedState();selected=new Set(state.providers.map(p=>p.id));date=BASE;persist('demo_reset');}});}
function bind(){const tenant=app.querySelector('#psw-tenant');if(tenant)tenant.onchange=()=>location.assign('/psw?dataset=demo&tenant='+encodeURIComponent(tenant.value));app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;query='';draw();window.scrollTo(0,0);});app.querySelector('#role-mode').onchange=e=>{mode=e.target.value;selected=new Set(isCoordinator()?state.providers.map(p=>p.id):[me().id]);discipline='all';draw();};app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));app.querySelectorAll('[data-visit]').forEach(b=>{b.onclick=()=>visitModal(b.dataset.visit);b.addEventListener('dragstart',e=>{if(!isCoordinator())return e.preventDefault();e.dataTransfer.setData('text/plain',b.dataset.visit);e.dataTransfer.effectAllowed='move';});});app.querySelectorAll('[data-client]').forEach(b=>b.onclick=()=>clientModal(b.dataset.client));app.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;draw();});app.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{date=b.dataset.date==='today'?BASE:addDate(date,(b.dataset.date==='next'?1:-1)*(view==='week'?7:1));draw();});['schedule-date','day-date','availability-date'].forEach(id=>{const e=app.querySelector('#'+id);if(e)e.onchange=()=>{if(validDate(e.value)){date=e.value;draw();}};});app.querySelectorAll('[data-provider]').forEach(e=>e.onchange=()=>{e.checked?selected.add(e.dataset.provider):selected.delete(e.dataset.provider);draw();});const buffer=app.querySelector('#buffer-form');if(buffer)buffer.onsubmit=e=>{e.preventDefault();const n=Number(new FormData(buffer).get('minutes'));if(!Number.isInteger(n)||n<0||n>90){buffer.querySelector('[data-buffer-error]').textContent='Use whole minutes from 0 to 90.';return;}const candidate=structuredClone(state);candidate.settings.travelBuffer=n;for(const v of candidate.visits.filter(v=>v.status!=='cancelled')){if(validateVisit(v,candidate,v.id)){buffer.querySelector('[data-buffer-error]').textContent='Existing visits would conflict. Adjust those visits before increasing the buffer.';return;}}state.settings.travelBuffer=n;persist('travel_buffer_changed',{minutes:n});};const disc=app.querySelector('#discipline');if(disc)disc.onchange=()=>{discipline=disc.value;draw();};app.querySelectorAll('[data-slot]').forEach(b=>{b.onclick=()=>{const [providerId,at]=b.dataset.slot.split('|');bookingModal({providerId,at});};b.ondragover=e=>{if(isCoordinator())e.preventDefault();};b.ondrop=e=>{e.preventDefault();if(!isCoordinator())return;const visit=state.visits.find(v=>v.id===e.dataTransfer.getData('text/plain'));if(!visit||!['planned','en_route'].includes(visit.status))return;const [providerId,start]=b.dataset.slot.split('|');bookingModal({visit:{...visit,providerId,start}});};});app.querySelectorAll('[data-book-date]').forEach(b=>b.onclick=()=>bookingModal({day:b.dataset.bookDate}));app.querySelectorAll('[data-time-review]').forEach(b=>b.onclick=()=>timeReview(b.dataset.timeReview));app.querySelectorAll('[data-availability]').forEach(b=>b.onclick=()=>availabilityModal(b.dataset.availability));app.querySelectorAll('[data-availability-review]').forEach(b=>b.onclick=()=>reviewAvailability(b.dataset.availabilityReview));app.querySelectorAll('[data-incident-review]').forEach(b=>b.onclick=()=>{if(!isCoordinator())return;const i=state.incidents.find(i=>i.id===b.dataset.incidentReview);modal('Record incident review',textarea('review','Review findings and follow-up completed'),{submit:'Close demo follow-up',onSubmit:v=>{i.status='closed';i.review=v.review;persist('incident_closed',{incidentId:i.id});}});});const search=app.querySelector('#client-search');if(search)search.oninput=e=>{const start=e.target.selectionStart;query=e.target.value.toLowerCase();draw();const next=app.querySelector('#client-search');next.focus();next.setSelectionRange(start,start);};}
draw();

}
